color or [color1, color2] for gradient.\n */\nconst PROVIDER_COLORS: Record<string, string | [string, string]> = {\n  anthropic: '#D97757',\n  bfl: '#ffffff',\n  bria: '#B6B6B6',\n  elevenlabs: '#B6B6B6',\n  bytedance: ['#00C8D2', '#325AB4'],\n  gemini: ['#3186FF', '#FABC12'],\n  grok: '#B6B6B6',\n  hitpaw: '#B6B6B6',\n  ideogram: '#B6B6B6',\n  kling: ['#0BF2F9', '#FFF959'],\n  ltxv: '#B6B6B6',\n  luma: ['#004EFF', '#00FFFF'],\n  magnific: ['#EA5A3D', '#F1A64A'],\n  meshy: ['#67B700', '#FA418C'],\n  minimax: ['#E2167E', '#FE603C'],\n  'moonvalley-marey': '#DAD9C5',\n  openai: '#B6B6B6',\n  pixverse: ['#B465E6', '#E8632A'],\n  quiver: '#B6B6B6',\n  recraft: '#B6B6B6',\n  reve: '#B6B6B6',\n  rodin: '#F7F7F7',\n  runway: '#B6B6B6',\n  sora: ['#6BB6FE', '#ffffff'],\n  'stability-ai': ['#9D39FF', '#E80000'],\n  tencent: ['#004BE5', '#00B3FE'],\n  topaz: '#B6B6B6',\n  tripo: ['#F6D85A', '#B6B6B6'],\n  veo: ['#4285F4', '#EB4335'],\n  vidu: ['#047FFE', '#40EDD8'],\n  wan: ['#6156EC', '#F4F3FD'],\n  wavespeed: '#B6B6B6'\n}\n\n/**\n * Extracts the provider name from a node category path.\n * e.g. \"api/image/BFL\" -> \"BFL\"\n */\nexport function getProviderName(category: string): string {\n  return category.split('/').at(-1) ?? ''\n}\n\n/**\n * Returns the icon class for an API node provider (e.g., BFL, OpenAI, Stability AI)\n * @param providerName - The provider name from the node category\n * @returns The icon class string (e.g., 'icon-[comfy--bfl]')\n */\nexport function getProviderIcon(providerName: string): string {\n  const iconKey = providerName.toLowerCase().replaceAll(/\\s+/g, '-')\n  return `icon-[comfy--${iconKey}]`\n}\n\n/**\n * Returns the border color(s) for an API node provider badge.\n * @param providerName - The provider name from the node category\n * @returns CSS color string or gradient definition\n */\nexport function getProviderBorderStyle(providerName: string): string {\n  const iconKey = providerName.toLowerCase().replaceAll(/\\s+/g, '-')\n  const colors = PROVIDER_COLORS[iconKey]\n\n  if (!colors) {\n    return '#525252' // neutral-600 fallback\n  }\n\n  if (Array.isArray(colors)) {\n    return `linear-gradient(90deg, ${colors[0]}, ${colors[1]})`\n  }\n\n  return colors\n}\n\n/**\n * Generates a unique category ID from a category group and title\n */\nexport function generateCategoryId(\n  categoryGroup: string,\n  categoryTitle: string\n) {\n  return `${categoryGroup.toLowerCase().replace(/\\s+/g, '-')}-${categoryTitle.toLowerCase().replace(/\\s+/g, '-')}`\n}\n"],"mappings":"uCAGA,IAAa,gBAAmB,IA+CvB,CA5CL,IAAK,sBACL,kBAAmB,gCAGnB,mBAAoB,uBACpB,MAAO,uBACP,mBAAoB,sBACpB,MAAO,sBACP,gBAAiB,qBACjB,KAAM,qBACN,mBAAoB,0BACpB,MAAO,0BACP,iBAAkB,qCAGlB,YAAa,4BACb,gBAAiB,4BAGjB,IAAK,qCACL,KAAM,qCACN,UAAW,qCAGX,eAAgB,qBAChB,YAAa,qBACb,iBAAkB,yBAClB,cAAe,yBAGf,gBAAiB,0BACjB,SAAU,0BAGV,WAAY,wBACZ,MAAO,wBAGP,UAAW,4BACX,WAAY,oCACZ,mBAAoB,4BAIf,EAAA,CAAQ,EAAW,YAAY,IAAM,wBAOxC,EAA6D,CACjE,UAAW,UACX,IAAK,UACL,KAAM,UACN,WAAY,UACZ,UAAW,CAAC,UAAW,SAAS,EAChC,OAAQ,CAAC,UAAW,SAAS,EAC7B,KAAM,UACN,OAAQ,UACR,SAAU,UACV,MAAO,CAAC,UAAW,SAAS,EAC5B,KAAM,UACN,KAAM,CAAC,UAAW,SAAS,EAC3B,SAAU,CAAC,UAAW,SAAS,EAC/B,MAAO,CAAC,UAAW,SAAS,EAC5B,QAAS,CAAC,UAAW,SAAS,EAC9B,mBAAoB,UACpB,OAAQ,UACR,SAAU,CAAC,UAAW,SAAS,EAC/B,OAAQ,UACR,QAAS,UACT,KAAM,UACN,MAAO,UACP,OAAQ,UACR,KAAM,CAAC,UAAW,SAAS,EAC3B,eAAgB,CAAC,UAAW,SAAS,EACrC,QAAS,CAAC,UAAW,SAAS,EAC9B,MAAO,UACP,MAAO,CAAC,UAAW,SAAS,EAC5B,IAAK,CAAC,UAAW,SAAS,EAC1B,KAAM,CAAC,UAAW,SAAS,EAC3B,IAAK,CAAC,UAAW,SAAS,EAC1B,UAAW,SACb,EAMA,SAAgB,gBAAgB,EAA0B,CACxD,OAAO,EAAS,MAAM,GAAG,CAAC,CAAC,GAAG,EAAE,GAAK,EACvC,CAOA,SAAgB,gBAAgB,EAA8B,CAE5D,MAAO,gBADS,EAAa,YAAY,CAAC,CAAC,WAAW,OAAQ,GACvC,EAAQ,EACjC,CAOA,SAAgB,uBAAuB,EAA8B,CAEnE,IAAM,EAAS,EADC,EAAa,YAAY,CAAC,CAAC,WAAW,OAAQ,GAC/B,GAU/B,OARK,EAID,MAAM,QAAQ,CAAM,EACf,0BAA0B,EAAO,GAAG,IAAI,EAAO,GAAG,GAGpD,EAPE,SAQX,CAKA,SAAgB,mBACd,EACA,EACA,CACA,MAAO,GAAG,EAAc,YAAY,CAAC,CAAC,QAAQ,OAAQ,GAAG,EAAE,GAAG,EAAc,YAAY,CAAC,CAAC,QAAQ,OAAQ,GAAG,GAC/G"}"""

